create table auditorias_acesso_contato (contato_id bigint not null, data_hora timestamp(6) not null, empresa_id bigint not null, id bigint generated by default as identity, usuario_email varchar(255), primary key (id));
create table avisos (ativo boolean not null, id bigint generated by default as identity, tipo varchar(32) not null check (tipo in ('MANUTENCAO','TUTORIAL','PRECO','COMUNICADO')), conteudo TEXT not null, link TEXT, titulo varchar(255) not null, primary key (id));
create table contatos (nao_contatar boolean not null, empresa_id bigint not null, final_telefone varchar(8), id bigint generated by default as identity, primeira_conversa_em timestamp(6), ultima_conversa_em timestamp(6), origem varchar(32) not null check (origem in ('CONVERSA','AGENDA')), numero_indice varchar(128) not null, nome varchar(1000), whatsapp_id varchar(1000) not null, primary key (id), constraint uk_contato_empresa_numero_indice unique (empresa_id, numero_indice));
create table data_especial (abre time(6), data date not null, fecha time(6), fechado boolean not null, empresa_id bigint not null, id bigint generated by default as identity, motivo varchar(120), primary key (id), unique (empresa_id, data));
create table empresa_emails_responsaveis_reuniao (ordem integer not null, empresa_id bigint not null, email varchar(255), primary key (ordem, empresa_id));
create table empresa_urls_galeria (ordem integer not null, empresa_id bigint not null, url TEXT, primary key (ordem, empresa_id));
create table empresas (ativo boolean, duracao_atendimento_minutos integer, intervalo_atendimentos_minutos integer, latitude float(53), lembrete_dias_antes integer, locacao_por_hora boolean, longitude float(53), permite_previsao_tempo boolean, permite_reserva_automatica boolean, previsao_tempo_ativa boolean, uf varchar(2), usaia boolean, data_exclusao timestamp(6), id bigint generated by default as identity, lembrete_horario_envio varchar(8), lembrete_modo varchar(32) check (lembrete_modo in ('DESLIGADO','SUGERIDO','AUTOMATICO')), cidade_previsao varchar(255), cidade_previsao_resolvida varchar(255), google_calendar_id varchar(255), lembrete_texto TEXT, link_foto_principal TEXT, link_galeria TEXT, link_google_maps TEXT, mensagem_saudacao TEXT, nome varchar(255), ramo_de_atuacao varchar(255), regras_locacao TEXT, sessao_whatsapp varchar(255) unique, tabela_de_precos TEXT, primary key (id));
create table horario_funcionamento (abre time(6), duracao_minutos integer, fecha time(6), fechado boolean not null, empresa_id bigint not null, id bigint generated by default as identity, perfil varchar(10) not null check (perfil in ('SEGUNDA','TERCA','QUARTA','QUINTA','SEXTA','SABADO','DOMINGO','FERIADO')), primary key (id), unique (empresa_id, perfil));
create table modulos_empresa (ativo boolean, ordem_exibicao integer, empresa_id bigint, id bigint generated by default as identity, codigo_acao varchar(255), texto_menu varchar(255), primary key (id));
create table reservas (data date not null, tentativas_envio integer not null, atualizada_em timestamp(6), contato_id bigint, empresa_id bigint not null, id bigint generated by default as identity, lembrete_enviado_em timestamp(6), lembrete_enviar_em timestamp(6), origem varchar(32) not null check (origem in ('AGENDA','BOT')), situacao varchar(32) not null check (situacao in ('SEM_CONTATO','AGUARDANDO_LEMBRETE','PRONTA_PARA_AVISAR','ENVIANDO','LEMBRETE_ENVIADO','SEM_RESPOSTA','CONFIRMADA_PELO_CLIENTE','CANCELAMENTO_SOLICITADO','CANCELADA_NA_AGENDA','ENCERRADA','FALHA_ENVIO','FALHA_AGENDA')), horario varchar(64), google_event_id varchar(128), titulo varchar(1000), primary key (id), constraint uk_reserva_empresa_google_event_id unique (empresa_id, google_event_id));
create table usuarios (empresa_id bigint, id bigint generated by default as identity, email varchar(255) not null unique, role varchar(255) not null check (role in ('ADMIN','SUPER_ADMIN','ADMIN_OPERACIONAL','ADMIN_LEITURA','CLIENTE')), senha varchar(255) not null, primary key (id));
